local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.speech
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.templates
rows[#rows+1]={" Know this, $r. Within Shaffar's chambers at the end of these tombs rests a creature of unimaginable power. It is held in check be the power of the stasis chamber. You must return to Ameer before you venture further if you wish to destroy it!"," 명심해라, $r. 이 무덤 끝 샤파르의 방에는 상상도 못 할 힘을 가진 존재가 잠들어 있다. 정지장 장치의 힘으로 억눌려 있지. 그걸 파괴하려면 더 깊이 들어가기 전에 반드시 아미르에게 돌아가라!"}
rows[#rows+1]={"\"$N WILL MAKE IT ALL BETTER\"","$N 모든 것을 더 좋게 만들 것입니다\""}
rows[#rows+1]={"\"Warchief Vol'jin.\" Does it sound absurd to you, $c? I, for one, certainly won't be taking orders from a troll.$b$b\010But, he put this little coalition together, and won the day. He's also proven to be impossible to kill - I admire that.$b$b\010Time to test what he's made of...","\"보유장 Vol'jin\". $c저는 트롤의 명령을 받지 않을 겁니다.$b$b\010하지만 그는 작은 연합을 모아서 승리를 거두었고, 또한 죽이는 것이 불가능한 것으로 입증되었습니다.$b$b\010그가 만든 것을 시험할 때가 됐어"}
rows[#rows+1]={"$964w, young $c.","$964w, 젊은 $c."}
rows[#rows+1]={"$966w, young $c.","$966w, 젊은 $c."}
rows[#rows+1]={"$C - I will consume your light!","$C|1이여;여;, 네 생명의 빛을 모조리 삼켜 버리겠다!"}
rows[#rows+1]={"$C departing Redridge!","$C 레드리지에서 출발!"}
rows[#rows+1]={"$C!  No mounts on the game grounds!","$C게임장에는 마운팅이 금지돼!"}
rows[#rows+1]={"$C! Come to my aid!","$C도와줘!"}
rows[#rows+1]={"$C! Look sharp. I smell the stench of Wildhammer nearby...","$C날카롭게 봐요, 근처에 와일드햄어의 냄새가 나고 있어요"}
rows[#rows+1]={"$C! This area's swarming with Kor'kron. Give us a hand?","$C이 지역은 코크론으로 가득 차 있어"}
rows[#rows+1]={"$C, Dame Auriferous has conveyed to me her great pleasure in the service that you have done us in the past. She wishes to extend to you her hope that you will continue to be a champion of sin'dorei interests here in the Ghostlands.","$C아우리페로스 부인께서 과거에 우리에게 베풀었던 봉사에 대해 큰 기쁨을 전해주셔서 여러분께 계속 귀신지에서 죄의 권익을 옹호해 주시길 희망합니다."}
rows[#rows+1]={"$C, I have something to ask of you.","$C, 당신에게 물어볼 게 있어요."}
rows[#rows+1]={"$C, I need more copper bars! There's a war brewing at the Gates of Ahn'Qiraj and we need supplies! The Alliance has collected $1997w and we need $1998w copper bars in total. If I don't get those copper bars, it's going to be my head on a platter!","$C, 더 많은 구리 바를 필요해요! 아안키라지의 문에서 전쟁이 벌어지고 있고, 우리는 물품이 필요해요! 얼라이언스는 $1997w를 수집했고, 우리는 총 $1998w의 구리 바를 필요로 합니다. 만약 제가 그 구리 바를 얻지 못한다면, 그것은 제 머리가 한 판에 있을 것입니다!"}
rows[#rows+1]={"$C, I would ask something of you.","$C, 제가 여러분께 물어볼 게 있어요."}
rows[#rows+1]={"$C, I'm going to need a little time to look into this possible business concerning the blood elves. Perhaps you have other tasks that need doing in the meantime?","$C피 엘프에 관한 일을 좀 조사해봐야겠어"}
rows[#rows+1]={"$C, are you certain you are ready to leave? Take a moment.","$C- 떠나고 싶다고 확신이 있으세요?"}
rows[#rows+1]={"$C, back on Azeroth, the Silverwing Sentinels hamper our progress in the woods. We need you there on the battlefront to push them back! You will earn great honor and reputation with the Warsong Outriders for helping us - join us now!","$C, 다시 아제로스, 은 날개 세티널은 숲에서 우리의 진전을 방해합니다. 우리는 당신이 전투 전선에 그들을 밀어 넣을 필요가 있습니다! 당신은 우리를 도와 대전 외향자와 큰 명성을 얻을 것입니다 - 지금 우리와 함께!"}
rows[#rows+1]={"$C, even our hardiest warriors and scouts will need use of the healing arts in the war to come at Ahn'Qiraj. And when there is no magical healing available, they must rely upon our efforts here.$B$BTo date I have collected $2088w runecloth bandages, out of $2090w needed. If you are willing, we should speak further on how you can do your part.","$C, 심지어 우리의 가장 용감한 전사들과 스카우트는 아안키라지에서 오는 전쟁에서 치유의 기술을 사용해야 할 것입니다.$B$B현재까지 필요 한 $2090w 중 $2088w의 룬 布 붕대를 수집 해 왔습니다. 여러분 의 의지를 인정 한다면, 여러분 의 역할 을 어떻게 할 수 있는지에 대해 더 자세히 이야기 할 수 있습니다."}
rows[#rows+1]={"$C, hold your attack, this is just a disguise!  I'm a spy working for the Lower City coalition out of Shattrath City.$B$BI hope you're here to help!","$C공격하지 마, 이건 위장일 뿐이야!$B$B도와줄게 됐으면 좋겠어요!"}
rows[#rows+1]={"$C, if you are looking for the Black Prince, you will find him upstairs.","$C만약 당신이 블랙 프린스를 찾고 있다면, 당신은 그를 위로 찾을 것입니다."}
rows[#rows+1]={"$C, is it not? Thank you for returning our brothers to us.","$C형제들을 다시 우리에게 돌려주셔서 감사합니다."}
rows[#rows+1]={"$C, look what they've done to our beloved land. The Scourge must be destroyed!","$C우리 사랑하는 땅이 어떻게 되었는지 보세요 스컬지 파괴되어야 합니다!"}
rows[#rows+1]={"$C, over here.","$C여기"}
rows[#rows+1]={"$C, please listen to what I have to say. The Alliance and Horde are preparing for a war with the Silithid and their masters in Ahn'Qiraj. Any assistance that you can lend will be greatly appreciated. As you can see, I am collecting thorium bars here for the war effort. We need to gather $2012w in total, and currently we have $2011w.","$C제가 말씀드릴 말을 들어주십시오 얼라이언스 그리고 호드 아인키라지에서 실리티드와 그들의 주인들과 전쟁을 준비하고 있습니다. 당신이 줄 수 있는 모든 도움이 매우 감사할 것입니다. $2012w 전체적으로, 현재 우리는 $2011w."}
rows[#rows+1]={"$C, the Horde has gathered all that it needs for the Ahn'Qiraj War! Now we wait for the puny Alliance to catch up. When they do, we'll begin transporting everything to Silithus. It should not be long after the buildup there is completed that the war will begin!","$C, 호드는 아안키라지 전쟁에 필요한 모든 것을 수집했습니다! 이제 우리는 작은 얼라이언스이 따라갈 때까지 기다립니다. 그들이 할 때, 우리는 모든 것을 실리투스로 운송하기 시작할 것입니다. 군대가 완료된 지 얼마 지나지 않아 전쟁이 시작 될 것입니다!"}
rows[#rows+1]={"$C, the cataclysm has crumbled the mountains and the South Sea has rushed in to drown Thousand Needles.$B$BWe need your help, now!","$C, 재앙은 산들을 무너뜨리고 남해가 밀레인 네일러스를 익사시키려고 달려왔다.$B$B당장 도와줘!"}
rows[#rows+1]={"$C, through the efforts of many we have managed to gather up all of the runecloth bandages that the Alliance feels it needs for the upcoming conflict. Were I you, I would ask some of the others here to see if they still have collection tasks that need fulfilling.","$C많은 사람들의 노력으로 우리는 룬클레드 가죽의 모든 배낭을 수집하는 데 성공했습니다 얼라이언스 제가 여러분처럼 여기 있는 다른 분들에게"}
rows[#rows+1]={"$C, up here! I could use a hand!","$C이리 올라와, 도움이 필요해"}
rows[#rows+1]={"$C, we are not ashamed to say that we are in need of all of the assistance that we can get in our fight at Warsong Gulch.  But there is greater honor to be had now than at any time in the past if you so choose to lend us your skills.  As well, the Silverwing Sentinels are sure to look more favorably upon your efforts on our behalf.  Will you join the battle?","$C, 우리는 우리가 워송 구치 전투에서 얻을 수 있는 모든 도움을 필요로 하는 것을 부끄러워하지 않습니다. 하지만 당신이 당신의 기술을 우리에게 빌려주기로 결정한다면 과거 어느 때보다 더 큰 영광이 있습니다. 또한, 은 날개 경호자들은 우리 대신 당신의 노력에 더 호의적으로 보리라. 당신은 전투에 합류 할 것인가?"}
rows[#rows+1]={"$C, we have a great need for your help in Warsong Gulch against the Silverwing Sentinels.  And there is even greater honor and reputation with the Warsong Outriders to be gained as well!  Do you have the courage to enter battle?","$C우리는 당신의 도움이 필요하고 있습니다. 그리고 더 큰 명예와 명성을 얻을 수 있습니다."}
rows[#rows+1]={"$C, we need your assistance at Warsong Gulch.  Will you aid us in our fight against the Warsong Outriders?","$C워싱글 구치에서 당신의 도움이 필요해요"}
rows[#rows+1]={"$C, you didn't happen to see a courier on your way here? We are awaiting word from Silvermoon City and their messenger is late!","$C여기로 가는 길에 택배를 본 적 없어? 실버문 도시와 그들의 사자가 늦었어!"}
rows[#rows+1]={"$C, you just earned yourself a beating.","$C, 당신은 방금 자신을 때려 얻었습니다."}
rows[#rows+1]={"$C, you saved me!  I owe you a debt that I can never repay.  I'll go see if I can help the others.","$C님이 절 구하셨군요! 평생 잊지 못할 신세를 졌습니다. 도움이 필요한 다른 친구는 없는지 찾아봐야겠습니다."}
rows[#rows+1]={"$C, you should know the Warchief doesn't trust the undead. Have you heard what happened at the Wrathgate?","$C, 당신은 워치퍼가 죽은자를 믿지 않는다는 것을 알아야 합니다."}
rows[#rows+1]={"$C... approach me...","$C... 내게 다가와..."}
rows[#rows+1]={"$C... you must be the one that's been helping these pitiful mistlurkers.","$C...이 비참한 미스클러커들을 도와주는 사람이야"}
rows[#rows+1]={"$Cs have no respect these days, I tell you.","$C는 요즘 존경받지 못해요"}
