rows[#rows+1]={"$n, slay any dragons today?","$n오늘 드래곤을 죽였어?"}
rows[#rows+1]={"$n, slay dragon?","$n, 드래곤 살인?"}
rows[#rows+1]={"$n, somehow I feel stronger from Mam'toth's blood.","$n어떻게든 매머토스의 피로 더 강해졌어요"}
rows[#rows+1]={"$n, stay here and help Taylor recover.","$n여기 있어 테일러가 회복할 수 있도록 도와줘"}
rows[#rows+1]={"$n, summon me again when you need to perform the ritual again.","$n다시 의식이 필요할 때 다시 불러주세요"}
rows[#rows+1]={"$n, terror of the skies, how are you doing?","$n, 하늘의 공포, 어떻게 지내세요?"}
rows[#rows+1]={"$n, thank goodness you're here!","$n고맙게도 여기 있어!"}
