rows[#rows+1]={"$n, with the crane's powers, you can jump over the flames!","$n크레인의 힘으로 불꽃을 뛰어넘을 수 있어!"}
rows[#rows+1]={"$n, wonderful to see you. Wonderful.","$n반갑습니다."}
